#[inline]
pub(crate) fn parse_object_type_extension(p: &mut GraphqlParser) -> ParsedSyntax {
    let m = p.start();

    p.bump(T![extend]);
    p.bump(T![type]);

    parse_name(p).or_add_diagnostic(p, expected_name);

    // implements interface is optional
    let implements_present = parse_implements_interface(p).is_present();

    let pos = p.source().position();
    DirectiveList.parse_list(p);
    let directive_empty = p.source().position() == pos;

    // fields definition is optional
    let fields_present = parse_fields_definition(p).is_present();

    // an object type extension must have at least one of an implements clause,
    // a set of directives, or a fields definition
    if !implements_present && directive_empty && !fields_present {
        p.error(expected_object_type_extension(p, p.cur_range()));
    }

    Present(m.complete(p, GRAPHQL_OBJECT_TYPE_EXTENSION))
